import React, { useState, useEffect } from 'react';
import axios from 'axios';

function Dashboard({ userId }) {
  const [meal, setMeal] = useState(null);
  const [imageData, setImageData] = useState(null);

  useEffect(() => {
    if (userId) {
      axios.get(`http://localhost:5000/meal/suggest/${userId}`).then(res => setMeal(res.data));
    }
  }, [userId]);

  const handleImageUpload = async (e) => {
    const formData = new FormData();
    formData.append('image', e.target.files[0]);
    const res = await axios.post('http://localhost:5000/meal/image', formData);
    setImageData(res.data);
  };

  if (!userId) return <p>Please sign in.</p>;

  return (
    <div style={{ padding: '20px' }}>
      <h1>Dashboard</h1>
      {meal && (
        <div>
          <h2>{meal.name}</h2>
          <p>Calories: {meal.calories}</p>
          <p>Ingredients: {meal.ingredients}</p>
          <p>Instructions: {meal.instructions}</p>
        </div>
      )}
      <input type="file" onChange={handleImageUpload} />
      {imageData && <p>Food: {imageData.food}, Calories: {imageData.calories}</p>}
    </div>
  );
}

export default Dashboard;
